import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
const EXE='/workspace/dataset/test6_executable';
function enc(str, how){
  if(how==='utf8') return Buffer.from(str,'utf8');
  if(how==='latin1') return Buffer.from(str,'latin1');
  if(how==='utf16le') return Buffer.from(str,'utf16le');
  if(how==='utf16be'){const b=Buffer.from(str,'utf16le');const o=Buffer.alloc(b.length);for(let i=0;i<b.length;i+=2){o[i]=b[i+1];o[i+1]=b[i];}return o;}
  throw new Error(how);
}
function k(pb,sb,it=1000,dk=16){return crypto.pbkdf2Sync(pb,sb,it,dk,'sha1').toString('hex');}
const cases = JSON.parse(process.argv[2]); // [[a,b,c,d,label],...]
for(const [a,b,c,d,label] of cases){
  const r = spawnSync(EXE, ['--a',a,'--b',b,'--c',c,'--d',d], {encoding:'buffer'});
  const out = r.stdout.toString('binary');
  const lines = out.split('\n');
  const preds = {};
  for(const how of ['utf8','latin1','utf16le','utf16be']){
    try{ preds[how] = k(enc(a,how),enc(b,how)); }catch(e){ preds[how]='ERR'; }
  }
  const match = Object.entries(preds).filter(([h,v])=>v===lines[0]).map(([h])=>h);
  console.log(JSON.stringify({label, exit:r.status, stdoutRaw: r.stdout.toString('binary'), stderr:r.stderr.toString('binary'), line0:lines[0], line1:lines[1], preds, matches:match, secondEqPred: lines[1]===k(enc(c,'utf8'),enc(d,'utf8'))}));
}
EOF
