import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
const EXE = '/workspace/dataset/test6_executable';
const k = (p, s, it = 1000, dk = 16) => crypto.pbkdf2Sync(p, s, it, dk, 'sha1').toString('hex');
function run(a, b, c, d) {
  const r = spawnSync(EXE, ['--a', a, '--b', b, '--c', c, '--d', d], { encoding: 'buffer' });
  return { status: r.status, lines: r.stdout.toString('binary').split('\n'), raw: r.stdout, err: r.stderr.toString('binary') };
}
const results = [];
// HMAC key boundary: pass lengths around SHA-1 block size 64
for (const n of [1, 20, 21, 63, 64, 65, 100, 128, 1000]) {
  const a = 'A'.repeat(n);
  const r = run(a, 'salt', 'x', 'y');
  const exp = k(Buffer.from(a, 'utf8'), Buffer.from('salt', 'utf8'));
  results.push({ test: `passlen=${n}`, got: r.lines[0], exp, ok: r.lines[0] === exp });
}
// salt lengths
for (const n of [0, 1, 19, 20, 21, 63, 64, 65, 100, 1000, 5000]) {
  const b = 'S'.repeat(n);
  const r = run('password', b, 'x', 'y');
  const exp = k(Buffer.from('password', 'utf8'), Buffer.from(b, 'utf8'));
  results.push({ test: `saltlen=${n}`, got: r.lines[0], exp, ok: r.lines[0] === exp });
}
// iteration count discrimination
{
  const r = run('password', 'salt', 'password', 'salt');
  for (const it of [1, 999, 1000, 1001, 2000, 4096]) {
    results.push({ test: `iters=${it}`, got: r.lines[0], exp: k(Buffer.from('password'), Buffer.from('salt'), it), ok: r.lines[0] === k(Buffer.from('password'), Buffer.from('salt'), it) });
  }
}
// CESU-8 / WTF-8 vs proper UTF-8 for astral
{
  const s = '\u{1F600}';
  const proper = Buffer.from(s, 'utf8'); // f0 9f 98 80
  const cesu = Buffer.concat([Buffer.from([0xed, 0xa0, 0xbd]), Buffer.from([0xed, 0xb8, 0x80])]);
  const r = run(s, s, 'x', 'y');
  results.push({ test: 'astral proper-utf8', got: r.lines[0], exp: k(proper, proper), ok: r.lines[0] === k(proper, proper), properHex: proper.toString('hex') });
  results.push({ test: 'astral CESU-8', got: r.lines[0], exp: k(cesu, cesu), ok: r.lines[0] === k(cesu, cesu), cesuHex: cesu.toString('hex') });
}
// independence / ordering
{
  const r1 = run('p1', 's1', 'p2', 's2');
  const r2 = run('p2', 's2', 'p1', 's1');
  results.push({ test: 'order-swap', a: r1.lines.slice(0, 2), b: r2.lines.slice(0, 2), ok: r1.lines[0] === r2.lines[1] && r1.lines[1] === r2.lines[0] });
  const r3 = run('same', 'same', 'same', 'same');
  results.push({ test: 'same-input-twice', l0: r3.lines[0], l1: r3.lines[1], ok: r3.lines[0] === r3.lines[1] });
}
// output shape
{
  const r = run('password', 'salt', 'password', 'salt');
  results.push({ test: 'byte-shape', totalLen: r.raw.length, hex: r.raw.toString('binary'), ok: r.raw.length === 66 && /^[0-9a-f]{32}\n[0-9a-f]{32}\n$/.test(r.raw.toString('binary')) });
}
for (const x of results) console.log(JSON.stringify(x));

