import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
const EXE = '/workspace/dataset/test6_executable';
function raw(args) {
  const r = spawnSync(EXE, args, { encoding: 'buffer' });
  return { status: r.status, out: r.stdout.toString('binary'), err: r.stderr.toString('binary') };
}
const k = (p, s, it = 1000, dk = 16) => crypto.pbkdf2Sync(p, s, it, dk, 'sha1').toString('hex');

// 1) shell-special / weird characters passed verbatim
const weird = [
  ['$HOME', 'dollar'],
  ['a"b', 'dquote'],
  ['a\\b', 'backslash'],
  ["a'b", 'squote'],
  ['a\nb', 'newline'],
  ['a\r\nb', 'crlf'],
  ['a\tb', 'tab'],
  ['`id`', 'backtick'],
  ['a;b|c&d', 'shell-meta'],
  ['*?[]', 'glob'],
  ['%s%d{0}', 'format'],
  ['--b', 'looks-like-option'],
  ['-x', 'leading-dash'],
];
for (const [v, label] of weird) {
  const r = raw(['--a', v, '--b', v, '--c', 'x', '--d', 'y']);
  const exp = k(Buffer.from(v, 'utf8'), Buffer.from(v, 'utf8'));
  console.log(JSON.stringify({ probe: 'verbatim:' + label, value: JSON.stringify(v), status: r.status, line0: r.out.split('\n')[0], exp, ok: r.out.split('\n')[0] === exp, err: r.err.slice(0, 160) }));
}

// 2) manual PBKDF2 construction check: counter big-endian 1, U1..U1000 xor
