import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
const EXE = '/workspace/dataset/test6_executable';
const k = (p, s) => crypto.pbkdf2Sync(p, s, 1000, 16, 'sha1').toString('hex');
function run(a, b) {
  const r = spawnSync(EXE, ['--a', a, '--b', b, '--c', 'x', '--d', 'y'], { encoding: 'buffer' });
  return { status: r.status, l0: r.stdout.toString('binary').split('\n')[0], err: r.stderr.toString('binary') };
}
// NFC vs NFD explicitly
const nfc = 'é';            // é precomposed
const nfd = 'é';           // e + combining acute
for (const [s, label] of [[nfc, 'NFC U+00E9'], [nfd, 'NFD e+U+0301']]) {
  const r = run(s, s);
  console.log(JSON.stringify({ probe: label, bytes: Buffer.from(s, 'utf8').toString('hex'), got: r.l0, expUtf8: k(Buffer.from(s, 'utf8'), Buffer.from(s, 'utf8')), ok: r.l0 === k(Buffer.from(s, 'utf8'), Buffer.from(s, 'utf8')) }));
}
console.log(JSON.stringify({ probe: 'NFC!==NFD', differ: run(nfc, nfc).l0 !== run(nfd, nfd).l0 }));

// Astral vs its two-surrogate-as-separate-chars — can't send lone surrogates via argv; instead
// verify 4-byte utf8 length effect: '\u{1F600}' (4 bytes) vs 'aaaa' (4 bytes) differ but same salt padding math
const s1 = '\u{1F600}';
console.log(JSON.stringify({ probe: 'astral byte length', utf8len: Buffer.from(s1, 'utf8').length, hex: Buffer.from(s1, 'utf8').toString('hex'), jsLength: s1.length }));

// Long astral password crossing the 64-byte HMAC block boundary
for (const n of [15, 16, 17, 25, 26]) {
  const a = s1.repeat(n); // 4n bytes utf8
  const r = run(a, 'salt');
  const exp = k(Buffer.from(a, 'utf8'), Buffer.from('salt', 'utf8'));
  console.log(JSON.stringify({ probe: `astral pass x${n} (${4 * n} bytes)`, got: r.l0, exp, ok: r.l0 === exp }));
}
// Mixed multibyte salt around block boundary
for (const n of [20, 21, 22]) {
  const b = '日'.repeat(n); // 3n bytes
  const r = run('pw', b);
  const exp = k(Buffer.from('pw', 'utf8'), Buffer.from(b, 'utf8'));
  console.log(JSON.stringify({ probe: `cjk salt x${n} (${3 * n} bytes)`, got: r.l0, exp, ok: r.l0 === exp }));
}

