import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
const EXE = '/workspace/dataset/test6_executable';
const k = (p, s) => crypto.pbkdf2Sync(p, s, 1000, 16, 'sha1').toString('hex');
function run(a, b, c, d) {
  const r = spawnSync(EXE, ['--a', a, '--b', b, '--c', c, '--d', d], { encoding: 'buffer' });
  return { status: r.status, raw: r.stdout, l0: r.stdout.toString('binary').split('\n')[0], l1: r.stdout.toString('binary').split('\n')[1], err: r.stderr.toString('binary') };
}
// huge inputs
{
  const a = 'x'.repeat(100000), b = 'y'.repeat(100000);
  const r = run(a, b, 'q', 'w');
  console.log(JSON.stringify({ probe: 'huge 100k pass+salt', status: r.status, got: r.l0, exp: k(Buffer.from(a), Buffer.from(b)), ok: r.l0 === k(Buffer.from(a), Buffer.from(b)) }));
}
// randomized fuzz over BMP+astral
{
  let fails = 0, n = 40;
  for (let i = 0; i < n; i++) {
    const rnd = (len) => { let s = ''; for (let j = 0; j < len; j++) { let cp; do { cp = Math.floor(Math.random() * 0x110000); } while (cp >= 0xD800 && cp <= 0xDFFF); s += String.fromCodePoint(cp); } return s; };
    const a = rnd(1 + Math.floor(Math.random() * 30)), b = rnd(Math.floor(Math.random() * 30));
    const c = rnd(1 + Math.floor(Math.random() * 8)), d = rnd(1 + Math.floor(Math.random() * 8));
    const r = run(a, b, c, d);
    const e0 = k(Buffer.from(a, 'utf8'), Buffer.from(b, 'utf8'));
    const e1 = k(Buffer.from(c, 'utf8'), Buffer.from(d, 'utf8'));
    if (r.l0 !== e0 || r.l1 !== e1) { fails++; console.log(JSON.stringify({ FAIL: true, a: [...a].map(x => x.codePointAt(0).toString(16)), b: [...b].map(x => x.codePointAt(0).toString(16)), got: [r.l0, r.l1], exp: [e0, e1], err: r.err.slice(0, 200) })); }
  }
  console.log(JSON.stringify({ probe: 'random unicode fuzz', trials: n, failures: fails }));
}
